class UniformAffineQuantizer(nn.Module):    def __init__(        self,        n_bits: int = 8,        symmetric: bool = False,        channel_wise: bool = False,        scale_method: str = "minmax",        leaf_param: bool = False,        prob: float = 1.0,    ):        super(UniformAffineQuantizer, self).__init__()        self.sym = symmetric        assert 2 <= n_bits <= 8, "bitwidth not supported"        self.n_bits = n_bits        self.n_levels = 2**self.n_bits        self.delta = 1.0        self.zero_point = 0.0        self.inited = True        self.leaf_param = leaf_param        self.channel_wise = channel_wise        self.eps = torch.tensor(1e-8, dtype=torch.float32)        self.scale_method = "mse"        self.one_side_dist = None        self.num = 100        self.running_min = None        self.running_max = None        self.prob = prob        self.is_training = False        self.timewise_quant_mode = False        self.fast_mode = False        self.now_t = None        self.timestep_params = {}    def change_timestep(self, t):        assert self.timewise_quant_mode        assert type(t) == int        if self.now_t is not None:            self.timestep_params[self.now_t] = [                self.delta,                self.zero_point,                self.inited,            ]        if t not in self.timestep_params:            self.timestep_params[t] = [1, 0, False]        self.delta, self.zero_point, self.inited = self.timestep_params[t]        self.now_t = t    def set_inited(self, inited: bool = True):        self.inited = inited    def update_quantize_range(self, x_min, x_max):        if self.running_min is None:            self.running_min = x_min            self.running_max = x_max        self.running_min = 0.1 * x_min + 0.9 * self.running_min        self.running_max = 0.1 * x_max + 0.9 * self.running_max        return self.running_min, self.running_max    def forward(self, x: torch.Tensor):        if self.inited is False:            if self.leaf_param:                self.delta, self.zero_point = self.init_quantization_scale(                    x.clone().detach(), self.channel_wise                )            else:                self.delta, self.zero_point = self.init_quantization_scale(                    x.clone().detach(), self.channel_wise                )        if self.fast_mode:            x_sim = (                (x / self.delta)                .round_()                .clamp_(-self.zero_point, self.n_levels - 1 - self.zero_point)                .mul_(self.delta)            )            return x_sim        x_int = round_ste(x / self.delta) + self.zero_point        x_quant = torch.clamp(x_int, 0, self.n_levels - 1)        x_dequant = (x_quant - self.zero_point) * self.delta        if self.is_training and self.prob < 1.0:            x_ans = torch.where(torch.rand_like(x) < self.prob, x_dequant, x)        else:            x_ans = x_dequant        return x_ans    def lp_loss(self, pred, tgt, p=2.0):        x = (pred - tgt).abs().pow(p)        if not self.channel_wise:            return x.mean()        else:            y = torch.flatten(x, 1)            return y.mean(1)    def calculate_qparams(self, min_val, max_val):        quant_min, quant_max = 0, self.n_levels - 1        min_val_neg = torch.min(min_val, torch.zeros_like(min_val))        max_val_pos = torch.max(max_val, torch.zeros_like(max_val))        scale = (max_val_pos - min_val_neg) / float(quant_max - quant_min)        scale = torch.max(scale, self.eps)        zero_point = quant_min - torch.round(min_val_neg / scale)        zero_point = torch.clamp(zero_point, quant_min, quant_max)        return scale, zero_point    def quantize(self, x: torch.Tensor, x_max, x_min):        delta, zero_point = self.calculate_qparams(x_min, x_max)        if self.channel_wise:            new_shape = [1] * len(x.shape)            new_shape[0] = x.shape[0]            delta = delta.reshape(new_shape)            zero_point = zero_point.reshape(new_shape)        x_int = torch.round(x / delta)        x_quant = torch.clamp(x_int + zero_point, 0, self.n_levels - 1)        x_float_q = (x_quant - zero_point) * delta        return x_float_q    def perform_2D_search(self, x):        if self.channel_wise:            y = torch.flatten(x, 1)            x_min, x_max = torch._aminmax(y, 1)            x_max = torch.max(x_max, torch.zeros_like(x_max))            x_min = torch.min(x_min, torch.zeros_like(x_min))        else:            x_min, x_max = torch._aminmax(x)        xrange = x_max - x_min        best_score = torch.zeros_like(x_min) + (1e10)        best_min = x_min.clone()        best_max = x_max.clone()        for i in range(1, self.num + 1):            tmp_min = torch.zeros_like(x_min)            tmp_max = xrange / self.num * i            tmp_delta = (tmp_max - tmp_min) / (2**self.n_bits - 1)            for zp in range(0, self.n_levels):                new_min = tmp_min - zp * tmp_delta                new_max = tmp_max - zp * tmp_delta                x_q = self.quantize(x, new_max, new_min)                score = self.lp_loss(x, x_q, 2.4)                best_min = torch.where(score < best_score, new_min, best_min)                best_max = torch.where(score < best_score, new_max, best_max)                best_score = torch.min(best_score, score)        return best_min, best_max    def perform_1D_search(self, x):        if self.channel_wise:            y = torch.flatten(x, 1)            x_min, x_max = torch._aminmax(y, 1)        else:            x_min, x_max = torch._aminmax(x)        xrange = torch.max(x_min.abs(), x_max)        best_score = torch.zeros_like(x_min) + (1e10)        best_min = x_min.clone()        best_max = x_max.clone()        if not self.channel_wise:            thres = (                xrange / self.num * torch.arange(1, self.num + 1, device=x.device)            )            new_min = torch.zeros_like(thres) if self.one_side_dist == "pos" else -thres            new_max = torch.zeros_like(thres) if self.one_side_dist == "neg" else thres            quant_min, quant_max = 0, self.n_levels - 1            scale = (new_max - new_min) / float(quant_max - quant_min)            scale = torch.max(scale, self.eps)            zero_point = -torch.round(new_min / scale)            zero_point = torch.clamp_(zero_point, quant_min, quant_max).view(-1, 1)            scale = scale.view(-1, 1)            scores = []            batch = 8            for i in range(0, self.num, batch):                x_int = (                    x.view(1, -1) / scale[i : i + batch]                ).round_()                x_int.clamp_(                    -zero_point[i : i + batch],                    self.n_levels - 1 - zero_point[i : i + batch],                )                x_sim = x_int.mul_(scale[i : i + batch])                score = (                    x_sim.sub_(x.view(1, -1)).abs_().pow_(2.4).mean(1)                )                scores.append(score)                del x_sim            ind = torch.argmin(torch.hstack(scores))            best_min1 = new_min[ind]            best_max1 = new_max[ind]            return best_min1, best_max1        for i in range(1, self.num + 1):            thres = xrange / self.num * i            new_min = torch.zeros_like(x_min) if self.one_side_dist == "pos" else -thres            new_max = torch.zeros_like(x_max) if self.one_side_dist == "neg" else thres            x_q = self.quantize(x, new_max, new_min)            score = self.lp_loss(x, x_q, 2.4)            best_min = torch.where(score < best_score, new_min, best_min)            best_max = torch.where(score < best_score, new_max, best_max)            best_score = torch.min(score, best_score)        return best_min, best_max    def get_x_min_x_max(self, x):        if self.scale_method != "mse":            raise NotImplementedError        if self.one_side_dist is None:            self.one_side_dist = (                "pos" if x.min() >= 0.0 else "neg" if x.max() <= 0.0 else "no"            )        if (            self.one_side_dist != "no" or self.sym        ):            best_min, best_max = self.perform_1D_search(x)        else:            best_min, best_max = self.perform_2D_search(x)        if self.leaf_param:            return self.update_quantize_range(best_min, best_max)        return best_min, best_max    def init_quantization_scale_channel(self, x: torch.Tensor):        with torch.no_grad():            x_min, x_max = self.get_x_min_x_max(x)            scale, zero_point = self.calculate_qparams(x_min, x_max)        return scale, zero_point    def init_quantization_scale(        self, x_clone: torch.Tensor, channel_wise: bool = False    ):        if channel_wise:            delta, zero_point = self.init_quantization_scale_channel(x_clone)            new_shape = [1] * len(x_clone.shape)            new_shape[0] = x_clone.shape[0]            delta = delta.reshape(new_shape)            zero_point = zero_point.reshape(new_shape)        else:            delta, zero_point = self.init_quantization_scale_channel(x_clone)        return delta, zero_point    def bitwidth_refactor(self, refactored_bit: int):        assert 2 <= refactored_bit <= 32, "bitwidth not supported"        self.n_bits = refactored_bit        self.n_levels = 2**self.n_bits    @torch.jit.export    def extra_repr(self):        return "bit={}, is_training={}, inited={}".format(            self.n_bits, self.is_training, self.inited        )

