        "scale_method": args.init_wmode,
        "symmetric": True,
    }
    aq_params = {
        "n_bits": args.n_bits_a,
        "channel_wise": False,
        "scale_method": args.init_amode,
        "leaf_param": True,
        "prob": args.prob,
        "symmetric": True,
    }

    qnn = QuantModel(
        model=model, weight_quant_params=wq_params, act_quant_params=aq_params
    )
    qnn.cuda()
    qnn.eval()
    if not args.disable_8bit_head_stem:
        print("Setting the first and the last layer to 8-bit")
        qnn.set_first_last_layer_to_8bit()

    qnn.disable_network_output_quantization()
    print("sampling calib data")
    if args.calib_im_mode == "random":
        cali_data = random_calib_data_generator(
            [1, 3, args.image_size, args.image_size],
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "raw":
        cali_data = raw_calib_data_generator(
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "raw_forward_t":
        cali_data = forward_t_calib_data_generator(
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    elif args.calib_im_mode == "noise_backward_t":
        cali_data = backward_t_calib_data_generator(
            model,
            args,
            args.calib_num_samples,
            "cuda",
            args.calib_t_mode,
            diffusion,
            args.class_cond,
        )
    else:
        raise NotImplementedError
    assert args.wwq is True
    kwargs = dict(
        cali_data=cali_data,
        iters=args.iters_w,
        weight=args.weight,
        b_range=(args.b_start, args.b_end),
        warmup=args.warmup,
        opt_mode="mse",
        wwq=args.wwq,
        waq=args.waq,
        order=args.order,
        act_quant=args.act_quant,
        lr=args.lr,
        input_prob=args.input_prob,
        keep_gpu=not args.keep_cpu,
    )

    if args.act_quant and args.order == "before" and args.awq is False:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )

    set_weight_quantize_params(qnn)
    if not args.use_adaround:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )
        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn
    else:
        def set_weight_act_quantize_params(module):
            if isinstance(module, QuantModule):
                layer_reconstruction(qnn, module, **kwargs)
            elif isinstance(module, BaseQuantBlock):
                block_reconstruction(qnn, module, **kwargs)
            else:
                raise NotImplementedError

        def recon_model(model: nn.Module):
            for name, module in model.named_children():
                if isinstance(module, QuantModule):
                    print("Reconstruction for layer {}".format(name))
                    set_weight_act_quantize_params(module)
                elif isinstance(module, BaseQuantBlock):
                    print("Reconstruction for block {}".format(name))
                    set_weight_act_quantize_params(module)
                else:
                    recon_model(module)

        recon_model(qnn)

        if args.act_quant and args.order == "after" and args.waq is False:
            set_act_quantize_params(
                qnn, cali_data=cali_data, awq=args.awq, order=args.order
            )

        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn

class DeepCacheSDHelper(object):
    def __init__(self, pipe=None):
        if pipe is not None: self.pipe = pipe

    def enable(self, pipe=None):
        assert self.pipe is not None
        self.reset_states()
        self.wrap_modules()

    def disable(self):
        self.unwrap_modules()
        self.reset_states()

    def set_params(self,cache_interval=1, cache_branch_id=0, skip_mode='uniform'):
        cache_layer_id = cache_branch_id % 3
        cache_block_id = cache_branch_id // 3
        self.params = {
            'cache_interval': cache_interval,
            'cache_layer_id': cache_layer_id,
            'cache_block_id': cache_block_id,
            'skip_mode': skip_mode
        }

    def is_skip_step(self, block_i, layer_i, blocktype = "down"):
        self.start_timestep = self.cur_timestep if self.start_timestep is None else self.start_timestep # For some pipeline that the first timestep != 0
        cache_interval, cache_layer_id, cache_block_id, skip_mode = \
            self.params['cache_interval'], self.params['cache_layer_id'], self.params['cache_block_id'], self.params['skip_mode']
        if skip_mode == 'uniform':
            if (self.cur_timestep-self.start_timestep) % cache_interval == 0: return False
        if block_i > cache_block_id or blocktype == 'mid':
            return True
        if block_i < cache_block_id: return False
        return layer_i >= cache_layer_id if blocktype == 'down' else layer_i > cache_layer_id

    def is_enter_position(self, block_i, layer_i):
        return block_i == self.params['cache_block_id'] and layer_i == self.params['cache_layer_id']

    def wrap_unet_forward(self):
        self.function_dict['unet_forward'] = self.pipe.unet.forward
        def wrapped_forward(*args, **kwargs):
            self.cur_timestep = list(self.pipe.scheduler.timesteps).index(args[1].item())
            result = self.function_dict['unet_forward'](*args, **kwargs)
            return result
        self.pipe.unet.forward = wrapped_forward

    def wrap_block_forward(self, block, block_name, block_i, layer_i, blocktype = "down"):
        self.function_dict[
            (blocktype, block_name, block_i, layer_i)
        ] = block.forward
        def wrapped_forward(*args, **kwargs):
            skip = self.is_skip_step(block_i, layer_i, blocktype)
            result = self.cached_output[(blocktype, block_name, block_i, layer_i)] if skip else self.function_dict[(blocktype, block_name,  block_i, layer_i)](*args, **kwargs)
            if not skip: self.cached_output[(blocktype, block_name, block_i, layer_i)] = result
            return result
        block.forward = wrapped_forward

    def wrap_modules(self):
        # 1. wrap unet forward
        self.wrap_unet_forward()
        # 2. wrap downblock forward
        for block_i, block in enumerate(self.pipe.unet.down_blocks):
            for (layer_i, attention) in enumerate(getattr(block, "attentions", [])):
                self.wrap_block_forward(attention, "attentions", block_i, layer_i)
            for (layer_i, resnet) in enumerate(getattr(block, "resnets", [])):
                self.wrap_block_forward(resnet, "resnet", block_i, layer_i)
            for downsampler in getattr(block, "downsamplers", []) if block.downsamplers else []:
                self.wrap_block_forward(downsampler, "downsampler", block_i, len(getattr(block, "resnets", [])))
            self.wrap_block_forward(block, "block", block_i, 0, blocktype = "down")
        # 3. wrap midblock forward
        self.wrap_block_forward(self.pipe.unet.mid_block, "mid_block", 0, 0, blocktype = "mid")
        # 4. wrap upblock forward
        block_num = len(self.pipe.unet.up_blocks)
        for block_i, block in enumerate(self.pipe.unet.up_blocks):
            layer_num = len(getattr(block, "resnets", []))
            for (layer_i, attention) in enumerate(getattr(block, "attentions", [])):
                self.wrap_block_forward(attention, "attentions", block_num - block_i - 1, layer_num - layer_i - 1, blocktype = "up")
            for (layer_i, resnet) in enumerate(getattr(block, "resnets", [])):
                self.wrap_block_forward(resnet, "resnet", block_num - block_i - 1, layer_num - layer_i - 1, blocktype = "up")
            for upsampler in getattr(block, "upsamplers", []) if block.upsamplers else []:
                self.wrap_block_forward(upsampler, "upsampler", block_num - block_i - 1, 0, blocktype = "up")
            self.wrap_block_forward(block, "block", block_num - block_i - 1, 0, blocktype = "up")

    def unwrap_modules(self):
        # 1. unet forward
        self.pipe.unet.forward = self.function_dict['unet_forward']
        # 2. downblock forward
        for block_i, block in enumerate(self.pipe.unet.down_blocks):
            for (layer_i, attention) in enumerate(getattr(block, "attentions", [])):
                attention.forward = self.function_dict[("down", "attentions", block_i, layer_i)]
            for (layer_i, resnet) in enumerate(getattr(block, "resnets", [])):
                resnet.forward = self.function_dict[("down", "resnet", block_i, layer_i)]
            for downsampler in getattr(block, "downsamplers", []) if block.downsamplers else []:
                downsampler.forward = self.function_dict[("down", "downsampler", block_i, len(getattr(block, "resnets", [])))]
            block.forward = self.function_dict[("down", "block", block_i, 0)]
        # 3. midblock forward
        self.pipe.unet.mid_block.forward = self.function_dict[("mid", "mid_block", 0, 0)]
        # 4. upblock forward
        block_num = len(self.pipe.unet.up_blocks)
        for block_i, block in enumerate(self.pipe.unet.up_blocks):
            layer_num = len(getattr(block, "resnets", []))
            for (layer_i, attention) in enumerate(getattr(block, "attentions", [])):
                attention.forward = self.function_dict[("up", "attentions", block_num - block_i - 1, layer_num - layer_i - 1)]
            for (layer_i, resnet) in enumerate(getattr(block, "resnets", [])):
                resnet.forward = self.function_dict[("up", "resnet", block_num - block_i - 1, layer_num - layer_i - 1)]
            for upsampler in getattr(block, "upsamplers", []) if block.upsamplers else []:
                upsampler.forward = self.function_dict[("up", "upsampler", block_num - block_i - 1, 0)]
            block.forward = self.function_dict[("up", "block", block_num - block_i - 1, 0)]

    def reset_states(self):
        self.cur_timestep = 0
        self.function_dict = {}
        self.cached_output = {}
        self.start_timestep = None

def get_T_to_0(self, model, x_T, T=None, enable_grad=False, upsample_to_64=True, **model_kwargs):
    if enable_grad:
        grad = th.enable_grad()
    else:
        grad = th.no_grad()
    with grad:
        if T == None:
            T = th.ones(x_T.shape[0], device=x_T.device) * self.sigma_max
        c_in = append_dims(self.get_c_in(T), x_T.ndim)
        if self.args.decoder_style == 'stylegan':
            out = model((c_in * x_T).view(x_T.shape[0],-1), model_kwargs['y'])
        else:
            if self.args.upsample_to_64 and upsample_to_64:
                x_T = F.interpolate(x_T, size=64, mode="bicubic")
            model_output = model(c_in * x_T, T, **model_kwargs)
            out = model_output
    return out

def get_recon_loss(self, decoder, x_start, x_end, loss1, step, **model_kwargs):
    if step % (2 * self.args.decoder_gan_frequency) == 0:
        T_to_0_estimate = self.get_T_to_0(decoder, x_end, enable_grad=True, **model_kwargs)
        self.fake_x = T_to_0_estimate
        T_to_0_target = x_start
        if x_start.shape[2] < 256:
            T_to_0_estimate = F.interpolate(T_to_0_estimate, size=224, mode="bilinear")
            T_to_0_target = F.interpolate(T_to_0_target, size=224, mode="bilinear")
        if self.args.loss_norm == 'lpips':
            decoder_distill = (self.feature_extractor(
                (T_to_0_estimate + 1) / 2.0,
                (T_to_0_target + 1) / 2.0, ))
        elif self.args.loss_norm == 'cnn_vit':
            distances, estimate_features, target_features = [], [], []
            estimate_features, target_features = get_xl_feature(self.args, T_to_0_estimate, T_to_0_target,
                                                                feature_extractor=self.feature_extractor, step=step)
            cnt = 0
            for _, _ in self.feature_extractor.items():
                for fe in list(estimate_features[cnt].keys()):
                    norm_factor = th.sqrt(th.sum(estimate_features[cnt][fe] ** 2, dim=1, keepdim=True))
                    est_feat = estimate_features[cnt][fe] / (norm_factor + 1e-10)
                    norm_factor = th.sqrt(th.sum(target_features[cnt][fe] ** 2, dim=1, keepdim=True))
                    tar_feat = target_features[cnt][fe] / (norm_factor + 1e-10)
                    distances.append(self.dist(est_feat, tar_feat))
                cnt += 1
            decoder_distill = th.cat([d.mean(dim=[2, 3]) for d in distances], dim=1).sum(dim=1)
        else:
            raise NotImplementedError
        decoder_distill = self.check_isnan(decoder_distill)
        if self.args.discriminator_adaptive_weight or self.args.decoder_adaptive_weight:
            if self.args.decoder_style == 'unet':
                loss1_grad_norm = th.norm(th.autograd.grad(decoder_distill.mean(), self.get_last_layer(decoder, self.args.data_name), retain_graph=True)[0])
            else:
                loss1_grad_norm = th.norm(th.autograd.grad(decoder_distill.mean(), decoder.module.get_last_layer(), retain_graph=True)[0])
        else:
            loss1_grad_norm = th.zeros_like(decoder_distill).mean()
        return decoder_distill, loss1_grad_norm
    return self.null(x_start)

def get_decoder_discriminator_loss(self, decoder, discriminator, x_start, x_end, loss1, step, learn_generator=False, loss1_grad_norm=0,
                                       recon=False, **model_kwargs):
    if step < self.args.pretraining_step:
        return self.null(x_start)
    if learn_generator:
        if step % (2 * self.args.decoder_gan_frequency) == 0:
            if recon:
                fake_x = self.fake_x
            else:
                if self.args.pretrained_input_size == 32 and self.args.wavelet_input:
                    fake_noise = self.dwt_forward(th.randn((x_end.shape[0], x_end.shape[1], self.sampling_input_size, self.sampling_input_size), device=dist_util.dev()))[0] * self.sigma_max
                else:
                    fake_noise = th.randn_like(x_end) * self.sigma_max
                fake_x = self.get_T_to_0(decoder, fake_noise, enable_grad=True, **model_kwargs)
            logits_fake = get_xl_feature(self.args, fake_x, feature_extractor=self.discriminator_feature_extractor,
                                                  discriminator=discriminator, step=step, decoder=True, **model_kwargs)
            g_loss = sum([(-l).mean() for l in logits_fake]) / len(logits_fake)
            adaptive_weight = self.get_adaptive_weight(decoder, loss1, g_loss, self.args.discriminator_adaptive_weight,
                                                       loss1_grad_norm=loss1_grad_norm, type_='decoder')
            discriminator_loss = adaptive_weight * g_loss
            if th.isnan(g_loss.mean()) or th.isnan(adaptive_weight):
                discriminator_loss = self.null(x_start)
        else:
            return self.null(x_start)
    else:
        if recon:
            fake_x = self.fake_x.detach()
        else:
            if self.args.pretrained_input_size == 32 and self.args.wavelet_input:
                fake_noise = self.dwt_forward(th.randn((x_start.shape[0], x_start.shape[1], self.sampling_input_size, self.sampling_input_size), device=dist_util.dev()))[0] * self.sigma_max
            else:
                fake_noise = th.randn(self.x_end_shape, device=dist_util.dev()) * self.sigma_max
            fake_x = self.get_T_to_0(decoder, fake_noise, **model_kwargs)
        real_x = x_start
        logits_fake, logits_real = get_xl_feature(self.args, fake_x, target=real_x.detach(),
                                                  feature_extractor=self.discriminator_feature_extractor,
                                                  discriminator=discriminator, step=step, decoder=True, grad=th.no_grad, **model_kwargs)
        loss_Dgen = sum([(F.relu(th.ones_like(l) + l)).mean() for l in logits_fake]) / len(logits_fake)
        loss_Dreal = sum([(F.relu(th.ones_like(l) - l)).mean() for l in logits_real]) / len(logits_real)
        discriminator_loss = loss_Dreal + loss_Dgen
        discriminator_loss = self.check_isnan(discriminator_loss)
    return discriminator_loss


@persistence.persistent_class
class SuperresGenerator(torch.nn.Module):
    def __init__(self,
        z_dim,  # Input latent (Z) dimensionality.
        z_mid_dim,
        c_dim,  # Conditioning label (C) dimensionality.
        w_dim,  # Intermediate latent (W) dimensionality.
        num_init_layers,
        img_resolution,
        img_channels,
        head_layers=7,
        up_factor=2,
        **synthesis_kwargs,
    ):
        assert up_factor in [2, 4, 8, 16], "Supported up_factors: [2, 4, 8, 16]"

        super().__init__()
        self.up_factor = up_factor

        self.synthesis = SynthesisNetwork(w_dim=w_dim, img_resolution=img_resolution, img_channels=img_channels, **synthesis_kwargs)
        self.mapping = MappingNetwork(z_dim=z_dim, z_mid_dim=z_mid_dim, c_dim=c_dim, w_dim=w_dim, num_ws=self.synthesis.num_ws,
                                      num_init_layers=num_init_layers)

        self.z_dim = z_dim
        self.c_dim = c_dim
        self.w_dim = w_dim
        self.img_channels = img_channels
        self.channel_base = self.synthesis.channel_base
        self.channel_max = self.synthesis.channel_max
        self.margin_size = self.synthesis.margin_size
        self.last_stopband_rel = self.synthesis.last_stopband_rel
        self.num_critical = self.synthesis.num_critical
        self.num_fp16_res = self.synthesis.num_fp16_res
        self.conv_kernel = self.synthesis.conv_kernel
        self.use_radial_filters = self.synthesis.use_radial_filters

        for name in reversed(self.synthesis.layer_names):
            if getattr(self.synthesis, name).is_critically_sampled:
                delattr(self.synthesis, name)
                self.synthesis.layer_names.pop()
        stem_len = len(self.synthesis.layer_names) + 1

        self.img_resolution = img_resolution * up_factor
        self.synthesis.img_resolution = self.img_resolution

        self.num_layers = stem_len + head_layers
        self.synthesis.num_layers = self.num_layers

        self.num_ws = stem_len + head_layers + 1
        self.mapping.num_ws = self.num_ws
        self.synthesis.num_ws = self.num_ws

        last_stem_layer = getattr(self.synthesis, self.synthesis.layer_names[-1])
        fparams = self.compute_superres_filterparams(up_factor, self.img_resolution, last_stem_layer, head_layers)

        self.head_layer_names = []
        for idx in range(head_layers + 1):
            prev = max(idx - 1, 0)
            is_torgb = (idx == head_layers)
            is_critically_sampled = (idx >= head_layers - self.num_critical)
            use_fp16 = (fparams.sampling_rates[idx] * (2 ** self.num_fp16_res) > self.img_resolution)
            layer = SynthesisLayer(
                w_dim=self.w_dim, is_torgb=is_torgb, is_critically_sampled=is_critically_sampled, use_fp16=use_fp16,
                in_channels=int(fparams.channels[prev]), out_channels= int(fparams.channels[idx]),
                in_size=int(fparams.sizes[prev]), out_size=int(fparams.sizes[idx]),
                in_sampling_rate=int(fparams.sampling_rates[prev]), out_sampling_rate=int(fparams.sampling_rates[idx]),
                in_cutoff=fparams.cutoffs[prev], out_cutoff=fparams.cutoffs[idx],
                in_half_width=fparams.half_widths[prev], out_half_width=fparams.half_widths[idx],
                conv_kernel=self.conv_kernel, use_radial_filters=self.use_radial_filters,
            )
            name = f'L{idx+stem_len}_{layer.out_size[0]}_{layer.out_channels}'
            setattr(self.synthesis, name, layer)
            self.synthesis.layer_names.append(name)
            self.head_layer_names.append(name)

    def compute_superres_filterparams(self, up_factor, img_resolution, last_stem_layer, head_layers, num_critical=2):
        first_cutoff = last_stem_layer.out_cutoff
        first_stopband = last_stem_layer.out_half_width + first_cutoff

        last_cutoff = img_resolution / 2
        last_stopband = last_cutoff * self.last_stopband_rel
        exponents = np.minimum(np.arange(head_layers + 1) / (head_layers - num_critical), 1)
        cutoffs = first_cutoff * (last_cutoff / first_cutoff) ** exponents
        stopbands = first_stopband * (last_stopband / first_stopband) ** exponents

        sampling_rates = np.exp2(np.ceil(np.log2(np.minimum(stopbands*2, img_resolution))))
        sampling_rates[0] = last_stem_layer.out_sampling_rate

        half_widths = np.maximum(stopbands, sampling_rates / 2) - cutoffs
        sizes = sampling_rates + self.margin_size * 2
        sizes[-2:] = img_resolution
        channels = np.rint(np.minimum((self.channel_base / 2) / cutoffs, self.channel_max))
        channels[0] = last_stem_layer.out_channels
        channels[-1] = self.img_channels

        fparams = dnnlib.EasyDict()
        fparams.cutoffs = cutoffs
        fparams.stopbands = stopbands
        fparams.sampling_rates = sampling_rates
        fparams.half_widths = half_widths
        fparams.sizes = sizes
        fparams.channels = channels
        return fparams


